// ---------- Frontbuch v30: Challenge-Rad (/tools/challenge/ und Overlay ?mode=challenge) ----------
// Die Challenge-Liste (291 Einträge, DE/EN/ES/FR) steht als window.FB_CHAL_ROWS vor diesem Skript (Build: challenge_data.py).
// Zeile: [id, stufe 0/1/2, Spieler-Bitmaske (1=Solo, 2=Duo, 4=3 Leute, 8=4 Leute), Squad-Challenge 0/1, de, en, es, fr].
// Auswahl: Eintrag zählt, wenn die gewählte Spielerzahl in seiner Liste steht; ab 2 Spielern kann man die Einzel-Challenges (ind) abwählen.
(function () {
  'use strict';
  const LV = ['leicht', 'mittel', 'schwer'];
  // „wahnsinn“ (frühere 4. Stufe) wird wie „schwer“ gelesen, damit alte Links/Overlay-URLs weiter funktionieren
  const LV_ALIAS = { leicht: 0, easy: 0, facil: 0, 'fácil': 0, facile: 0, '1': 0, mittel: 1, medium: 1, media: 1, moyen: 1, '2': 1,
    schwer: 2, hard: 2, dificil: 2, 'difícil': 2, difficile: 2, '3': 2, wahnsinn: 2, insane: 2, locura: 2, folie: 2, '4': 2 };
  const TX = {
    de: { title: 'Challenge-Rad', lv: ['Leicht', 'Mittel', 'Schwer'], pl: ['Solo', 'Duo', '3 Leute', '4 Leute'], solo: 'Solo', squad: 'Squad', none: 'Keine Challenge passt zu diesen Filtern.', spin: 'Drehen' },
    en: { title: 'Challenge Wheel', lv: ['Easy', 'Medium', 'Hard'], pl: ['Solo', 'Duo', '3 players', '4 players'], solo: 'Solo', squad: 'Squad', none: 'No challenge matches these filters.', spin: 'Spin' },
    es: { title: 'Ruleta de retos', lv: ['Fácil', 'Media', 'Difícil'], pl: ['Solo', 'Dúo', '3 jugadores', '4 jugadores'], solo: 'Solo', squad: 'Escuadra', none: 'Ningún reto coincide con estos filtros.', spin: 'Girar' },
    fr: { title: 'Roue des défis', lv: ['Facile', 'Moyen', 'Difficile'], pl: ['Solo', 'Duo', '3 joueurs', '4 joueurs'], solo: 'Solo', squad: 'Escouade', none: 'Aucun défi ne correspond à ces filtres.', spin: 'Lancer' }
  };
  const LI = { de: 4, en: 5, es: 6, fr: 7 };
  const COL = ['#22c55e', '#facc15', '#f97316'];
  const ICON = ['🟢', '🟡', '🟠'];

  function build() {
    const ALL = (window.FB_CHAL_ROWS || []).map(r => ({ id: r[0], lv: r[1], pm: r[2], squad: !!r[3], t: { de: r[4], en: r[5], es: r[6], fr: r[7] } }));
    const BYID = new Map(ALL.map(c => [c.id.toUpperCase(), c]));
    const has = (c, p) => !!(c.pm & (1 << (p - 1)));
    const players = c => [1, 2, 3, 4].filter(p => has(c, p));
    // Filter f = { p: 1–4, levels: [0,1,2], ind: Einzel-Challenges bei p > 1 dazu }
    const norm = f => ({ p: [1, 2, 3, 4].includes(+(f && f.p)) ? +f.p : 1, levels: f && f.levels && f.levels.length ? f.levels : [0, 1, 2], ind: !f || f.ind !== false });
    const match = f => { const g = norm(f); return c => has(c, g.p) && g.levels.includes(c.lv) && (g.p === 1 || g.ind || c.squad); };
    const list = f => ALL.filter(match(f));
    const count = f => list(f).length;
    const counts = f => [0, 1, 2].map(l => count(Object.assign({}, norm(f), { levels: [l] })));
    const get = id => BYID.get(String(id || '').trim().toUpperCase()) || null;
    const rnd = () => { try { const a = new Uint32Array(1); crypto.getRandomValues(a); return a[0] / 4294967296; } catch (e) { return Math.random(); } };
    function roll(f, avoid) {
      const L = list(f);
      if (!L.length) return null;
      let c = L[Math.floor(rnd() * L.length)];
      if (avoid && L.length > 1 && c.id === avoid.id) c = L[(L.indexOf(c) + 1 + Math.floor(rnd() * (L.length - 1))) % L.length];
      return c;
    }
    const parts = (c, lang) => {
      const T = TX[lang] || TX.de, text = c.t[lang] || c.t.de;
      return { id: c.id, lv: c.lv, lvName: T.lv[c.lv], text, title: text, rule: '', squad: c.squad, players: players(c), icon: ICON[c.lv] };
    };
    // Rad-Segmente: n Einträge der Auswahl, davon der Gewinner (falls angegeben)
    function sample(f, n, must) {
      const L = list(f).filter(c => !must || c.id !== must.id);
      for (let i = L.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [L[i], L[j]] = [L[j], L[i]]; }
      const out = L.slice(0, Math.max(0, n - (must ? 1 : 0)));
      if (must) out.splice(Math.floor(rnd() * (out.length + 1)), 0, must);
      return out;
    }
    return { all: ALL, list, count, counts, get, roll, parts, sample, players, rnd, norm };
  }

  function parseLevels(s) {
    if (!s) return null;
    const out = [...new Set(String(s).toLowerCase().split(/[\s,;|+]+/).map(x => LV_ALIAS[x]).filter(x => x !== undefined))].sort();
    return out.length ? out : null;
  }
  const levelsParam = L => (!L || L.length >= 3 ? '' : L.map(x => LV[x]).join(','));

  // ---------- Rad (SVG). Zeiger rechts: ein Segment liegt bei Winkel 0 (3-Uhr-Position), Text verläuft waagerecht nach außen.
  const NS = 'http://www.w3.org/2000/svg', R = 250, HUB = 52, TXT_FROM = 70;
  function short(s, n) {
    s = String(s);
    if (s.length <= n) return s;
    const cut = s.slice(0, n - 1), sp = cut.lastIndexOf(' ');
    return (sp > n * 0.55 ? cut.slice(0, sp) : cut).replace(/[\s,:;.\-–(]+$/, '') + '…';
  }
  function mk(tag, attrs, txt) {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  function Wheel(svg, opt) {
    opt = opt || {};
    const eng = opt.engine, N = opt.segments || 10, maxChars = opt.maxChars || 21;
    let items = [], rot = 0, lang = opt.lang || 'de', winner = -1, raf = 0;
    svg.setAttribute('viewBox', '-262 -262 560 524');
    svg.setAttribute('role', 'img');
    svg.innerHTML = '';
    const rotG = mk('g', { class: 'wh-rot' }), segG = mk('g', { class: 'wh-segs' });
    rotG.appendChild(segG);
    const hub = mk('g', { class: 'wh-hub' });
    hub.appendChild(mk('circle', { r: HUB + 6, class: 'wh-ring' }));
    hub.appendChild(mk('circle', { r: HUB, class: 'wh-hubc' }));
    const hubT = mk('text', { class: 'wh-hubt', y: 2 }, opt.hubText || '🎲'); hub.appendChild(hubT);
    const ptr = mk('path', { class: 'wh-ptr', d: 'M 232 0 L 282 -19 L 282 19 Z' });
    svg.appendChild(mk('circle', { r: R + 8, class: 'wh-rim' })); svg.appendChild(rotG); svg.appendChild(hub); svg.appendChild(ptr);
    const seg = n => 360 / n;
    function path(a0, a1) {
      const r = x => x * Math.PI / 180, p = (a, rad) => [(rad * Math.cos(r(a))).toFixed(2), (rad * Math.sin(r(a))).toFixed(2)];
      const A = p(a0, R), B = p(a1, R);
      return `M0 0 L${A[0]} ${A[1]} A${R} ${R} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${B[0]} ${B[1]} Z`;
    }
    function draw() {
      segG.innerHTML = '';
      const n = items.length || 1, a = seg(n);
      items.forEach((c, i) => {
        const th = i * a, g = mk('g', { class: 'wh-seg', 'data-i': i, 'data-id': c.id, 'data-lv': c.lv });
        g.appendChild(mk('path', { d: path(th - a / 2, th + a / 2), fill: COL[c.lv], 'fill-opacity': i % 2 ? '.82' : '.62', class: 'wh-p' }));
        const sepA = th - a / 2, r = sepA * Math.PI / 180;
        g.appendChild(mk('line', { x1: 0, y1: 0, x2: (R * Math.cos(r)).toFixed(2), y2: (R * Math.sin(r)).toFixed(2), class: 'wh-sep' }));
        const t = mk('text', { x: R - 14, y: 0, class: 'wh-t', transform: `rotate(${th})` }, short(c.t[lang] || c.t.de, maxChars));
        g.appendChild(t);
        segG.appendChild(g);
      });
      setRot(rot);
      segG.querySelectorAll('.wh-seg').forEach(g => g.classList.toggle('win', +g.dataset.i === winner));
      svg.classList.toggle('has-win', winner >= 0);
    }
    function setRot(d) { rot = d; rotG.setAttribute('transform', `rotate(${d.toFixed(3)})`); }
    // Winkel (0–360), bei dem Segment i unter dem Zeiger steht
    const target = (i, n, off) => ((-(i * seg(n) + off)) % 360 + 360) % 360;
    function idx() {   // welches Segment liegt gerade am Zeiger
      const n = items.length, a = seg(n), cur = (((-rot) % 360) + 360) % 360;
      return Math.round(cur / a) % n;
    }
    return {
      el: svg,
      get items() { return items; }, get rotation() { return rot; }, get winner() { return winner; },
      setLang(l) { lang = l; draw(); },
      // Segmente setzen (z. B. Stichprobe der aktuellen Auswahl)
      set(list) { items = list.slice(); winner = -1; draw(); },
      // Gewinner c auf das Rad bringen: steht er schon drauf, bleibt das Rad; sonst ersetzt er das Segment gegenüber dem Zeiger
      place(c) {
        let i = items.findIndex(x => x.id === c.id);
        if (i < 0) {
          const n = items.length, far = (idx() + Math.round(n / 2)) % n;
          items[far] = c; i = far;
        }
        return i;
      },
      // Drehen: Ziel-Segment i, Dauer ms (0 = ohne Animation); onTick(segment) für Klicks
      spin(i, ms, onTick) {
        cancelAnimationFrame(raf);
        const n = items.length, a = seg(n), jitter = (Math.random() - 0.5) * a * 0.62;
        winner = -1; svg.classList.remove('has-win'); svg.classList.add('spinning');
        draw();
        const from = ((rot % 360) + 360) % 360, base = target(i, n, jitter);
        const turns = 5 + Math.floor(Math.random() * 3);
        const to = rot - from + 360 * turns + base;
        const done = () => { setRot(to); winner = i; svg.classList.remove('spinning'); draw(); };
        if (!ms) { done(); return Promise.resolve(i); }
        return new Promise(res => {
          const t0 = performance.now(), r0 = rot; let lastSeg = idx();
          const step = now => {
            const k = Math.min(1, (now - t0) / ms), e = 1 - Math.pow(1 - k, 4);
            setRot(r0 + (to - r0) * e);
            const s = idx(); if (s !== lastSeg) { lastSeg = s; if (onTick) onTick(s); }
            if (k < 1) raf = requestAnimationFrame(step); else { done(); res(i); }
          };
          raf = requestAnimationFrame(step);
        });
      },
      stop() { cancelAnimationFrame(raf); svg.classList.remove('spinning'); },
      setHub(t) { hubT.textContent = t; },
      hub, svg
    };
  }

  window.FBChallenge = { build, TX, LV, COL, ICON, parseLevels, levelsParam, Wheel, short, LI };
})();
